insert into public.tourist_spots(id,name,description,history,category,address,latitude,longitude,image_url,opening_hours,entrance_fee_note,tips,distance_from_town,is_active) values
  ('bustos-heritage-park','Bustos Heritage Park','A central heritage stop in Bustos and the starting point shared by all three Tric-Gabay tour packages.','This public park highlights local identity and serves as a convenient orientation point for a tour of Bustos.','heritage','Bustos, Bulacan',14.9532835,120.9186307,'assets/images/bustos_heritage_park.jpg','Open daily','Free','["A good first stop for the tour","Bring water and sun protection"]'::jsonb,0.2,true),
  ('sta-cruz-chapel','Sta. Cruz Chapel','A neighborhood chapel in Talampas, also mapped as Holy Cross Chapel, and included in the TRIC LAKBAY route.','A local faith stop included in the supplied Tric-Gabay tour package.','church','Bustos, Bulacan',14.9344482,120.9070123,'assets/images/san_isidro_labrador_parish.jpg','Check locally','Free','["Dress respectfully","Keep voices low during services"]'::jsonb,2.4,true),
  ('sta-monica-chapel','Sta. Monica Chapel','A chapel in Bonga Mayor that appears in every supplied tour package.','A recurring faith stop on the official Tric-Gabay package routes.','church','Bustos, Bulacan',14.9578495,120.9437551,'assets/images/sto_nino_tugyaw_festival.jpg','Check locally','Free','["Dress respectfully","Confirm service times before visiting"]'::jsonb,2.8,true),
  ('sto-nino-church','Sto. Nino Church','The Sto. Nino Parish Church in Poblacion, a landmark stop on TRIC LAKBAY and TRIC TUKLAS.','The parish church is one of the best-known religious landmarks in central Bustos.','church','Bustos, Bulacan',14.9550547,120.9096725,'assets/images/sto_nino_tugyaw_festival.jpg','Check parish schedule','Free','["Dress modestly","Avoid disrupting Mass or private prayer"]'::jsonb,1,true),
  ('zenys-minasa','Zenny''s Minasa Pasalubong','A local pasalubong stop for Bustos minasa and the final stop in all three supplied packages.','Minasa is a signature local delicacy and a popular take-home treat from Bustos.','market','Bustos, Bulacan',14.9530664,120.9192362,'assets/images/minasa_festival.jpg','Check store hours','No entrance fee','["Ask about available box sizes","Buy near the end of the tour"]'::jsonb,0.3,true),
  ('st-peter-chapel','St. Peter Chapel','The Chapel of Saint Peter under Sto. Nino Parish, included in the TRIC SAYA route.','A local Catholic chapel serving the surrounding Bustos community.','church','Bustos, Bulacan',14.9432705,120.9069568,'assets/images/san_isidro_labrador_parish.jpg','Check locally','Free','["Dress respectfully","Confirm chapel access before visiting"]'::jsonb,1.8,true),
  ('sto-nino-chapel','Sto. Nino Chapel','A local Sto. Nino faith stop included in the TRIC SAYA package.','This stop follows the name and route supplied in the tour package document.','church','Bustos, Bulacan',14.949086,120.9115939,'assets/images/sto_nino_tugyaw_festival.jpg','Check locally','Free','["Dress respectfully","Confirm chapel access before visiting"]'::jsonb,0.9,true),
  ('perpetual-help-chapel','Nuestra Senora del Perpetuo','Our Lady of Perpetual Help Chapel at Sitio Pitong Gatang, included in TRIC TUKLAS.','A community chapel under Sto. Nino Parish in Bustos.','church','Bustos, Bulacan',14.955398,120.9177589,'assets/images/san_isidro_labrador_parish.jpg','Check locally','Free','["Dress respectfully","Keep voices low during services"]'::jsonb,0.2,true),
  ('sto-rosario-chapel','Sto. Rosario Chapel','A chapel in Bonga Menor and a faith stop on the TRIC TUKLAS route.','A local Catholic chapel serving the Bonga Menor community.','church','Bustos, Bulacan',14.9504841,120.9327939,'assets/images/sto_nino_tugyaw_festival.jpg','Check locally','Free','["Dress respectfully","Confirm chapel access before visiting"]'::jsonb,1.6,true),
  ('immaculate-conception-chapel','Our Lady of Immaculate','Our Lady of the Immaculate Conception Chapel in Malamig, included in TRIC TUKLAS.','A local Catholic chapel serving the Malamig community.','church','Bustos, Bulacan',14.9365935,120.9277048,'assets/images/san_isidro_labrador_parish.jpg','Check locally','Free','["Dress respectfully","Keep voices low during services"]'::jsonb,2.2,true),
  ('galilee-wailing-wall','Galilee Wailing Wall','A themed landmark in Bustos and one of the distinctive stops on the TRIC TUKLAS route.','This attraction is included by name in the supplied tour package document.','other','Bustos, Bulacan',14.944234,120.908274,'assets/images/galilee_wonderland_resort.jpg','Check locally','Check locally','["Confirm access before visiting","Allow time for photos"]'::jsonb,1.6,true),
  ('s1','Bustos Dam Eco Park','A scenic eco-park located near one of the longest sector dams in the world. Ideal for picnics, photography, and relaxing by the riverbank.','Constructed in 1926, the Bustos Dam was originally built to provide irrigation to local farmlands. It has since become a popular recreational spot.','nature','Bustos, Bulacan',14.9546077,120.9535507,'assets/images/bustos_dam_eco_park.jpg','6:00 AM – 5:00 PM','₱50','["Best visited during sunrise or sunset","Great for family picnics","Always be careful near the water"]'::jsonb,3.5,true),
  ('s3','Bustos Public Market','The bustling commercial hub of Bustos, where locals buy fresh produce, meats, and the town''s famous local delicacies.','A long-standing trading center that has fueled the local economy, connecting farmers, artisans, and consumers for decades.','market','Bustos, Bulacan',14.9514976,120.9172582,'assets/images/bustos_public_market.jpg','4:00 AM – 6:00 PM','Free','["Go early in the morning for the freshest produce","Don''t forget to buy Minasa cookies","Haggling is part of the experience"]'::jsonb,0.1,true),
  ('s5','Mercado Ancestral House','A well-preserved heritage stone house featuring intricate Baroque carvings and classic Filipino-Spanish architectural elements.','Dating back to the mid-19th century, this house is a testament to the affluent lifestyle of the early principalia in Bustos.','heritage','Bustos, Bulacan',14.9506629,120.9294725,'assets/images/mercado_ancestral_house.jpg','Exterior viewing only from the public road. Do not enter the property. (Private Property)','Free (Roadside viewing)','["Best appreciated during daylight","Respect the privacy of the current residents","Located in the historic district of Bonga Menor"]'::jsonb,1.5,true),
  ('s6','La Florentina Resort','A popular destination for locals and tourists, offering beautiful swimming pools and modern amenities in a nature-inspired setting.','Developed to cater to the growing demand for leisure facilities in Bustos, it has become a staple venue for family gatherings and events.','other','Bustos, Bulacan',14.9473511,120.9393883,'assets/images/la_florentina_resort.jpg','8:00 AM – 5:00 PM (Day Swim)','₱150 - ₱250','["Book in advance during summer months","Ideal for family reunions and team building","Cottages are available for rent"]'::jsonb,2.2,true),
  ('s7','Malamig Park Resort','A family-friendly resort known for its wave pools and exciting water slides, providing a fun and refreshing getaway.','One of the pioneering wave pool resorts in the area, offering affordable leisure and recreation for Bulakenyos over the years.','other','Bustos, Bulacan',14.9339711,120.9273098,'assets/images/galilee_wonderland_resort.jpg','8:00 AM – 5:00 PM','₱200','["Arrive early to secure the best cottages","Wave pool schedules are announced regularly","Expect large crowds during the summer"]'::jsonb,3,true),
  ('s8','Galilee Wonderland Resort','A uniquely themed resort with large pools and various biblical and whimsical statues, perfect for a fun day out.','Formerly known as Galilee Mansion, it was rebranded and expanded to include more attractions, merging recreation with unique thematic elements.','other','Bustos, Bulacan',14.9426537,120.9095893,'assets/images/galilee_wonderland_resort.jpg','8:00 AM – 5:00 PM','₱150','["Explore the different themed areas for great photos","Kid-friendly with specialized kiddie pools","Event spaces available for booking"]'::jsonb,1.8,true),
  ('s9','General Alejo Santos Bridge','A vital bridge crossing the Angat River, providing a scenic view of the water and surrounding landscapes, especially at sunset.','Named in honor of General Alejo Santos, a WWII hero and former Secretary of National Defense, this bridge is a key infrastructural link in Bulacan.','heritage','Bustos, Bulacan',14.9565923,120.9073392,'assets/images/general_alejo_santos_bridge.jpg','Open 24 hours','Free','["Perfect spot for sunset photography","Be mindful of traffic when walking","Connects Bustos to Baliuag"]'::jsonb,1,true),
  ('s10','Bahay at Yaman ni San Martin de Porres Inc.','A charitable institution and orphanage with stunning architecture inspired by the traditional stone houses of Batanes.','Founded to provide shelter and education to children in need, it grew into a self-sustaining community with beautifully constructed facilities.','heritage','Bustos, Bulacan',14.9360174,120.9426398,'assets/images/bahay_at_yaman_san_martin.jpg','By appointment only','Donation','["Contact management before visiting","Donations are welcome and highly appreciated","Respect the privacy of the children and staff"]'::jsonb,2.5,true),
  ('s11','Cafe Apolonio and Restaurant sa Bahay Na Bato','A historic Bahay na Bato turned into a charming restaurant, offering a unique dining experience amidst antique furnishings and classic architecture.','Originally an ancestral house built in the 1850s, it has been carefully preserved and repurposed to showcase the culinary and cultural heritage of Bustos.','heritage','Bustos, Bulacan',14.9504491,120.9290193,'assets/images/cafe_apolonio_bahay_na_bato.jpg','Temporarily Closed','Free (Restaurant purchases)','["Check their social media for reopening updates","A must-visit for heritage enthusiasts when open","Located in the heritage zone of Bonga Menor"]'::jsonb,1.4,true),
  ('s12','Cunanan Ancestral House','An impressive ancestral home that showcases the typical prosperous lifestyle of Filipino families during the late Spanish and early American periods.','Part of the rich collection of old houses in Bonga Menor, it has withstood the test of time, reflecting the town''s glorious past.','heritage','Bustos, Bulacan',14.9526049,120.9372526,'assets/images/galilee_wonderland_resort.jpg','Exterior viewing only from the public road. Do not enter the property. (Private Property)','Free (Roadside viewing)','["Best viewed as part of a heritage walking tour","Observe the intricate details on the facade","Please respect the property and do not trespass"]'::jsonb,2,true),
  ('s13','Lopez Ancestral House','Another jewel in Bustos'' crown of ancestral houses, featuring classic wood and stone elements that characterize Philippine colonial architecture.','Once the residence of a prominent local family, it serves as a silent witness to the historical events that shaped the municipality.','heritage','Bustos, Bulacan',14.9544661,120.9200347,'assets/images/galilee_wonderland_resort.jpg','Exterior viewing only from the public road. Do not enter the property. (Private Property)','Free (Roadside viewing)','["Located near the town center","Great addition to a cultural photography tour","Appreciate the classic capiz shell windows"]'::jsonb,0.3,true),
  ('s14','Cafe Portillo Bustos','A cozy and modern cafe offering a great selection of coffee and pastries, serving as a popular hangout spot for locals and visitors.','Established to provide a contemporary coffee culture experience in Bustos, blending modern tastes with local hospitality.','other','Bustos, Bulacan',14.9560029,120.9094761,'assets/images/galilee_wonderland_resort.jpg','9:00 AM – 9:00 PM','Free','["Perfect place to relax after a day of touring","Try their signature coffee blends","A popular study and remote work spot"]'::jsonb,0.6,true),
  ('s15','San Isidro Labrador Parish Church - Liciada','A beautiful parish church serving the spiritual needs of the community in Liciada, known for its peaceful ambiance and dedicated parishioners.','Dedicated to San Isidro Labrador, the patron saint of farmers, reflecting the strong agricultural roots of the local community.','church','Bustos, Bulacan',14.907861,120.92909,'assets/images/san_isidro_labrador_parish.jpg','6:00 AM – 6:00 PM','Free','["Attend a Sunday mass for the full community experience","Enjoy the quiet and serene environment","Located a bit further from the town center"]'::jsonb,5.5,true),
  ('s16','El Reloj del Centenario de Bustos (Bustos Clock Tower)','A prominent clock tower that serves as a modern landmark in Bustos, commemorating the town''s history and progress.','Built as part of the centennial celebrations, it stands as a symbol of Bustos'' continuous march towards development while honoring its past.','heritage','Bustos, Bulacan',14.9548746,120.9190243,'assets/images/bustos_clock_tower.jpg','Open 24 hours','Free','["Easily visible from the main roads","A great meeting point in the town center","Beautifully lit at night"]'::jsonb,0.1,true),
  ('s17','Bustos Welcome Arch','The grand entrance arch of the municipality, greeting visitors with local designs and serving as a boundary marker.','Erected to formally welcome travelers and showcase the pride of Bustosenyos, marking the boundary with neighboring towns.','heritage','Bustos, Bulacan',14.9485074,120.9580958,'assets/images/bustos_welcome_arch.jpg','Open 24 hours','Free','["A classic photo op for road-trippers","Be careful of traffic when taking photos","Marks the transition into the town"]'::jsonb,4.5,true),
  ('s18','Summer Place Resort','A refreshing local resort that offers a cool escape during the hot summer months, featuring well-maintained pools and recreational facilities.','A favored destination for local excursions and a quick getaway for those wanting to relax without traveling far from town.','other','Bustos, Bulacan',14.9561022,120.9504986,'assets/images/summer_place_resort.jpg','8:00 AM – 5:00 PM','₱150','["Great for casual swimming and small parties","Inquire about exclusive rentals","Bring your own food and drinks"]'::jsonb,3.8,true),
  ('s19','Daily Bread Organic Farm','A serene organic farm advocating for sustainable agriculture, offering visitors a glimpse into eco-friendly farming practices and fresh produce.','Established to promote healthy living and sustainable farming, it has become an educational destination for nature lovers and students.','nature','Bustos, Bulacan',14.939125,120.9421563,'assets/images/daily_bread_organic_farm.jpg','8:00 AM – 4:00 PM','₱100','["Try their fresh organic meals if available","Wear comfortable walking shoes","Learn about their composting and farming techniques"]'::jsonb,3,true),
  ('s20','Minasa Festival','The premier annual cultural festival of Bustos, celebrating the town''s famous Minasa cookies with colorful street dances and parades.','Initiated to promote local tourism and the traditional Minasa cookie industry, which dates back to the Spanish era when the cookies were made for the elite.','other','Bustos, Bulacan',14.9534,120.9189,'assets/images/minasa_festival.jpg','Every January (Schedule varies)','Free','["Plan your visit around the second week of January","Expect large crowds and road closures","Don''t miss the street dancing competition"]'::jsonb,0.2,true);
insert into public.tour_packages(id,name,description,is_active) values
  ('tric-lakbay','TRIC LAKBAY','A five-stop Bustos route combining the heritage park, community chapels, the parish church, and a minasa pasalubong stop.',true),
  ('tric-saya','TRIC SAYA','A five-stop chapel trail that begins at Bustos Heritage Park and ends with local minasa pasalubong.',true),
  ('tric-tuklas','TRIC TUKLAS','The most complete package, with eight ordered stops covering Bustos heritage, chapels, the parish church, Galilee Wailing Wall, and minasa pasalubong.',true);
